-- 907: Heat treatment calculators -- every heat-treatment time and service price as a real database calculator.
--
-- GENERATED by scripts/generate-heat-treatment-calculators-migration.ts from
-- src/modules/bom-items/costing/heat/calculators/heat-treatment-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- The heat-treatment formulas (straightening rate, oven loads, HIP load time, the
-- weight-priced service) were held in TypeScript, and the Heat Treatment rows of
-- process_calculator_mappings (migration 826) had calculator_id NULL, so the cost
-- dialogs could not open the calculator behind a line.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Heat Treatment catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Heat Treatment - Priced by Weight
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Heat Treatment - Priced by Weight$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Heat Treatment - Priced by Weight$q$, 'process', 'single', false, true, true, $q$A heat-treatment service priced by weight: Unit Weight Cost x batch weight, or the Min Batch Cost below the Min Batch Weight, times the case-depth multiplier (1 when the process has none), per part. Cycle Time is the handling time for the weight of the part (tblHandlingTimes).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$A heat-treatment service priced by weight: Unit Weight Cost x batch weight, or the Min Batch Cost below the Min Batch Weight, times the case-depth multiplier (1 when the process has none), per part. Cycle Time is the handling time for the weight of the part (tblHandlingTimes).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Part Weight$q$, $q$Part Weight (kg)$q$, $q$number$q$, $q$kg$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Batch Size$q$, $q$Batch Size$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Unit Weight Cost$q$, $q$Unit Weight Cost (USD/kg)$q$, $q$number$q$, $q$USD/kg$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Min Batch Cost$q$, $q$Min Batch Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Min Batch Weight$q$, $q$Min Batch Weight (kg)$q$, $q$number$q$, $q$kg$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Case Depth Multiplier$q$, $q$Case Depth Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Handling Time$q$, $q$Handling Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 7, true),
    (v_id, $q$Batch Weight$q$, $q$Batch Weight (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q${Part Weight} * {Batch Size}$q$, 8, false),
    (v_id, $q$Batch Service Cost$q$, $q$Batch Service Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q$IF({Batch Weight} < {Min Batch Weight}, {Min Batch Cost}, {Batch Weight} * {Unit Weight Cost}) * {Case Depth Multiplier}$q$, 9, false),
    (v_id, $q$Service Cost per Part$q$, $q$Service Cost per Part (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Batch Service Cost} / {Batch Size}$q$, 10, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Handling Time}$q$, 11, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Heat Treatment - Priced by Weight$q$
  WHERE process_group = $q$Heat Treatment$q$ AND operation IN ($q$Additional Temper$q$, $q$Atmosphere Oil Harden$q$, $q$Carbonitride$q$, $q$Carburize$q$, $q$Cryogenic Freeze$q$, $q$High Speed Steel Harden$q$, $q$High Temp Vacuum Anneal$q$, $q$Induction Harden$q$, $q$Low Temp Vacuum Anneal$q$, $q$Solution$q$, $q$Spring Steel Harden$q$, $q$Stainless Steel Harden$q$, $q$Standard Anneal$q$, $q$Standard Temper$q$, $q$Stress Relief$q$, $q$Vacuum Air Harden$q$, $q$Vacuum Air Harden with High Temper$q$, $q$Vacuum Temper$q$);
END
$calc$;

