-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Heat Treatment - Priced by Weight$q$, 11, 18),
    ($q$Heat Treatment - Certification$q$, 4, 1),
    ($q$Heat Treatment - Straighten$q$, 2, 1),
    ($q$Heat Treatment - Age$q$, 5, 1),
    ($q$Heat Treatment - Hot Isostatic Pressing$q$, 12, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Heat Treatment$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 907: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
